IN_C = 64
H = 512
W = 1024
OUT_C = 128
KH = 3
KW = 3
H_OUT = H - KH + 1
W_OUT = W - KW + 1

@avelang.jit
def simple_kernel(
    X: al.Tensor((8, 64, 512, 1024), al.bf16),
    W: al.Tensor((128, 64, 3, 3), al.bf16),
    Y: al.Tensor((8, 128, H_OUT, W_OUT), al.f32),
):
    for n in al.range(8):
        for oc in al.range(128):
            for o0 in al.range(H_OUT):
                for o1 in al.range(W_OUT):
                    acc = al.convert(0.0, al.f32)
                    g = oc // 64
                    ic_base = g * 64
                    for ic_local in al.range(64):
                        ic = ic_base + ic_local
                        for k0 in al.range(3):
                            for k1 in al.range(3):
                                i0 = o0 + k0
                                i1 = o1 + k1
                                if i0 < 512 and i1 < 1024:
